# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! Integration tests for the public crate surface.
//!
//! These tests link against the crate as a downstream consumer would: they can
//! only use what `src/lib.rs` re-exports. Treat them as the regression suite
//! for the crate's public contract — if a change breaks a test here, it is a
//! breaking change for users.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use template::{Error, greet};

#[test]
fn greeting_is_available_to_consumers() {
    assert_eq!(greet("Rust").unwrap(), "Hello, Rust!");
}

#[test]
fn errors_are_available_to_consumers() {
    assert_eq!(greet("").unwrap_err(), Error::EmptyName);
}

//! Unit tests for the crate-wide error type.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::*;

#[test]
fn renders_a_human_readable_message() {
    assert_eq!(Error::EmptyName.to_string(), "name must not be empty");
}

#[test]
fn is_a_standard_error() {
    fn assert_error<E: std::error::Error>(_: &E) {}

    assert_error(&Error::EmptyName);
}

//! Unit tests for the contract version and its bind rule.

use super::{CONTRACT_VERSION, binds, is_compatible};

#[test]
fn the_shipped_contract_version_is_pinned() {
    assert_eq!(CONTRACT_VERSION, (1, 0));
}

#[test]
fn the_contract_binds_to_itself() {
    assert!(is_compatible(CONTRACT_VERSION));
}

#[test]
fn a_newer_minor_on_the_module_side_binds() {
    assert!(is_compatible((1, 1)));
    assert!(is_compatible((1, 97)));
}

#[test]
fn an_older_minor_on_the_module_side_is_rejected() {
    // A host built against 1.4 cannot call a 1.2 module: the members it names
    // may not be served.
    assert!(!binds((1, 4), (1, 2)));
    assert!(binds((1, 4), (1, 4)));
}

#[test]
fn a_different_major_is_rejected() {
    assert!(!is_compatible((0, 0)));
    assert!(!is_compatible((2, 0)));
    assert!(!is_compatible((2, 97)));
}

//! Unit tests for the bus name table.

use super::{INTERFACE, METHODS, OBJECT_PATH, methods};

#[test]
fn the_object_path_is_the_interface_in_path_form() {
    let expected = format!("/{}", INTERFACE.replace('.', "/"));
    assert_eq!(OBJECT_PATH, expected);
}

#[test]
fn every_member_is_listed_exactly_once() {
    let mut sorted = METHODS.to_vec();
    sorted.sort_unstable();
    let mut deduplicated = sorted.clone();
    deduplicated.dedup();
    assert_eq!(sorted, deduplicated);
}

#[test]
fn the_method_table_holds_the_declared_members() {
    assert_eq!(METHODS, [methods::GREET]);
}

#[test]
fn no_member_name_is_empty() {
    assert!(METHODS.iter().all(|method| !method.is_empty()));
}

//! Tests for the `TinyBus` module adapter and its declared surface.

use super::{GreetingService, setup};
use template_bus::{GreetRequest, GreetResponse, names};
use tinybus::broker::Broker;
use tinybus::transport::memory::MemoryBus;
use tinybus::{Connection, Interface};

#[test]
fn declared_methods_match_the_dispatch_table() {
    let methods = GreetingService
        .members()
        .into_iter()
        .map(|member| member.to_string())
        .collect::<Vec<_>>();

    assert_eq!(methods, names::METHODS.to_vec());
}

#[test]
fn the_served_interface_name_matches_the_contract() {
    assert_eq!(GreetingService.name().to_string(), names::INTERFACE);
}

#[tokio::test]
async fn module_serves_greetings_over_a_real_bus() -> tinybus::Result<()> {
    let bus = MemoryBus::new();
    Broker::new().spawn(bus.clone());

    let service = Connection::connect(bus.connect().await?).await?;
    setup(service.clone()).await?;

    let client = Connection::connect(bus.connect().await?).await?;
    let proxy = client.proxy(names::INTERFACE, names::OBJECT_PATH, names::INTERFACE)?;
    let reply: GreetResponse = proxy
        .call(names::methods::GREET, (GreetRequest::new("Ferris"),))
        .await?;

    assert_eq!(reply, GreetResponse::new("Hello, Ferris!"));
    Ok(())
}

#[tokio::test]
async fn module_rejects_an_empty_name_over_the_bus() -> tinybus::Result<()> {
    let bus = MemoryBus::new();
    Broker::new().spawn(bus.clone());

    let service = Connection::connect(bus.connect().await?).await?;
    setup(service.clone()).await?;

    let client = Connection::connect(bus.connect().await?).await?;
    let proxy = client.proxy(names::INTERFACE, names::OBJECT_PATH, names::INTERFACE)?;
    let result = proxy
        .call::<GreetResponse>(names::methods::GREET, (GreetRequest::new("   "),))
        .await;

    let Err(error) = result else {
        return Err(tinybus::Error::failed(
            "whitespace-only names unexpectedly succeeded",
        ));
    };
    assert!(error.to_string().contains("name must not be empty"));
    Ok(())
}

//! Unit tests for the greeting module.
//!
//! Unit tests live next to the code they cover and may reach into private
//! items. Tests of the public contract belong in `tests/` instead.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::*;

#[test]
fn greets_a_named_person() {
    assert_eq!(greet("Ferris").unwrap(), "Hello, Ferris!");
}

#[test]
fn trims_the_name() {
    assert_eq!(greet("  Ferris  ").unwrap(), "Hello, Ferris!");
}

#[test]
fn rejects_an_empty_name() {
    assert_eq!(greet("").unwrap_err(), Error::EmptyName);
}

#[test]
fn rejects_a_whitespace_only_name() {
    assert_eq!(greet(" \t\n ").unwrap_err(), Error::EmptyName);
}

//! Unit tests for the `Greet` payloads.
//!
//! These pin the serde representation. It is the wire form: a host and a module
//! that disagree about a field name fail at runtime with a decode error, so the
//! shape is asserted here rather than assumed.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::{GreetRequest, GreetResponse};

#[test]
fn a_request_serializes_to_its_wire_form() {
    let encoded = serde_json::to_value(GreetRequest::new("Ferris")).unwrap();
    assert_eq!(encoded, serde_json::json!({ "name": "Ferris" }));
}

#[test]
fn a_response_serializes_to_its_wire_form() {
    let encoded = serde_json::to_value(GreetResponse::new("Hello, Ferris!")).unwrap();
    assert_eq!(encoded, serde_json::json!({ "greeting": "Hello, Ferris!" }));
}

#[test]
fn a_request_round_trips_through_json() {
    let request = GreetRequest::new("  Ferris  ");
    let encoded = serde_json::to_string(&request).unwrap();
    assert_eq!(
        serde_json::from_str::<GreetRequest>(&encoded).unwrap(),
        request
    );
}

#[test]
fn a_response_round_trips_through_json() {
    let response = GreetResponse::new("Hello, Ferris!");
    let encoded = serde_json::to_string(&response).unwrap();
    assert_eq!(
        serde_json::from_str::<GreetResponse>(&encoded).unwrap(),
        response
    );
}

#[test]
fn a_request_missing_its_name_is_rejected() {
    let decoded = serde_json::from_value::<GreetRequest>(serde_json::json!({}));
    assert!(decoded.is_err());
}

#[test]
fn a_response_missing_its_greeting_is_rejected() {
    let decoded = serde_json::from_value::<GreetResponse>(serde_json::json!({}));
    assert!(decoded.is_err());
}

#[test]
fn constructors_accept_both_borrowed_and_owned_names() {
    assert_eq!(
        GreetRequest::new(String::from("Ferris")),
        GreetRequest::new("Ferris")
    );
    assert_eq!(
        GreetResponse::new(String::from("Hi")),
        GreetResponse::new("Hi")
    );
}
